<span class="line"><span style="color:#61AFEF;">docker</span><span style="color:#98C379;"> images</span><span style="color:#D19A66;"> -f</span><span style="color:#98C379;"> &quot;label=version=1.0&quot;</span><span style="color:#7F848E;font-style:italic;">  # 按标签过滤</span></span>
